
-- Reshuffle the original 80 so the right answer isn't usually option B
-- (skips any question in a battle that is waiting or live right now).
with src as (
  select q.id, q.options, q.correct from public.bank_questions q
  where q.id in (select id from public.bank_questions order by id limit 80)
    and not exists (select 1 from public.battles b where b.status in ('waiting', 'live') and q.id = any (b.q_ids))),
perm as (
  select s.id, o.val, (o.idx - 1) = s.correct as is_key, random() as r
  from src s cross join lateral jsonb_array_elements(s.options) with ordinality as o(val, idx)),
ranked as (select id, val, is_key, row_number() over (partition by id order by r) - 1 as pos from perm),
agg as (select id, jsonb_agg(val order by pos) as opts, (max(pos) filter (where is_key))::int as newc from ranked group by id)
update public.bank_questions b set options = agg.opts, correct = agg.newc from agg where b.id = agg.id;
